          "ਜੇਠ ਅਤੇ ਹਾੜ੍ਹ ਵਿੱਚ ਲੂਆਂ ਤੇ ਗਰਮੀ ਹੁੰਦੀ ਹੈ, ਇਸ ਲਈ ਅਸੀਂ ਅੰਦਰ ਰਹਿੰਦੇ ਹਾਂ। ਸਾਉਣ ਵਿੱਚ ਬੱਦਲ ਵੱਸਦੇ ਹਨ ਤੇ ਅੰਬ-ਜਾਮਣ ਪੱਕਦੇ ਹਨ।",
          "ਅੱਸੂ ਵਿੱਚ ਮੌਸਮ ਨਿਰਾਲਾ ਹੁੰਦਾ ਹੈ, ਨਾ ਗਰਮੀ ਨਾ ਪਾਲਾ। ਮੱਘਰ ਵਿੱਚ ਕੋਟ-ਸਵੈਟਰ ਪਾਏ ਜਾਂਦੇ ਹਨ।",
