      summary: "ਸਵਰਨ ਹੁਸ਼ਿਆਰਪੁਰੀ ਦੀ ਇਸ ਕਵਿਤਾ ਵਿੱਚ ਮਾਤਾ ਗੁਜਰੀ ਜੀ ਛੋਟੇ ਸਾਹਿਬਜ਼ਾਦਿਆਂ ਨੂੰ ਸੂਬੇ ਦੇ ਦਰਬਾਰ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਹਿੰਮਤ ਰੱਖਣ ਅਤੇ ਸਿੱਖੀ ਉੱਤੇ ਪੱਕੇ ਰਹਿਣ ਦੀ ਸਿੱਖਿਆ ਦਿੰਦੇ ਹਨ।",
