      section: "ਪੰਜਾਬੀ ਪੁਸਤਕ",
      summary: "ਸ਼ਹੀਦ ਕਰਤਾਰ ਸਿੰਘ ਸਰਾਭਾ ਦੀ ਇਸ ਕਵਿਤਾ ਵਿੱਚ ਦੇਸ ਲਈ ਫਾਂਸੀ ਚੜ੍ਹਨ ਵਾਲਾ ਸ਼ਹੀਦ ਦੇਸਵਾਸੀਆਂ ਨੂੰ ਆਪਣੀ ਯਾਦ ਰੱਖਣ, ਦੇਸ ਨਾਲ ਧੋਖਾ ਨਾ ਕਰਨ ਅਤੇ ਹਿੰਮਤ ਨਾ ਹਾਰਨ ਦਾ ਸੁਨੇਹਾ ਦਿੰਦਾ ਹੈ।",
