          "ਸਾਡੀ ਮੌਤ ਨਾਲ ਦੇਸਵਾਸੀਆਂ ਦੇ ਦਿਲਾਂ ਵਿੱਚ ਵਤਨ ਦਾ ਪਿਆਰ ਜਾਗ ਜਾਵੇ। ਦੇਸ ਨਾਲ ਧੋਖਾ ਕਰ ਕੇ ਕੌਮ ਦੇ ਮੱਥੇ ਉੱਤੇ ਦਾਗ਼ ਨਹੀਂ ਲਾਉਣਾ।",
