          "ਕੁਹਾੜਾ ਬੋਲਿਆ ਕਿ ਮੈਂ ਰੁੱਖ ਨਹੀਂ ਵੱਢ ਸਕਦਾ ਕਿਉਂਕਿ ਖੇਤ ਵਿੱਚ ਇੱਕੋ ਰੁੱਖ ਬਚਿਆ ਹੈ ਅਤੇ ਪੰਛੀ ਆਲ੍ਹਣੇ ਕਿੱਥੇ ਪਾਉਣਗੇ। ਫਿਰ ਕਹੀ ਨੇ ਵੀ ਮਿੱਟੀ ਪੁੱਟਣ ਤੋਂ ਨਾਂਹ ਕਰ ਦਿੱਤੀ।",
