          "ਅਮਰੀਕ ਸਿੰਘ ਦਾ ਪੁੱਤਰ ਗੁਰਦੀਪ ਆਪਣੇ ਜਨਮ ਦਿਨ ਉੱਤੇ ਜਿੰਨੇ ਸਾਲ ਦਾ ਹੋਇਆ, ਓਨੇ ਬੂਟੇ ਲਾਉਣ ਲਈ ਲੈ ਆਇਆ। ਅਮਰੀਕ ਸਿੰਘ ਨੇ ਰੁੱਖ ਵੱਢਣ ਦੀ ਥਾਂ ਟੋਏ ਪੁੱਟ ਕੇ ਬੂਟੇ ਲਾਉਣ ਦਾ ਫ਼ੈਸਲਾ ਕੀਤਾ ਅਤੇ ਕਹੀ ਖਿੜ-ਖਿੜ ਹੱਸਣ ਲੱਗੀ।",
