          "ਉਸ ਨੇ ਨਾਂ ਖ਼ੁਦ ਚੁਣਿਆ ਅਤੇ ਕਰਨਾਲ ਦੇ ਟੈਗੋਰ ਬਾਲ-ਨਿਕੇਤਨ ਵਿੱਚ ਪੜ੍ਹੀ। ਬਚਪਨ ਵਿੱਚ ਉਹ ਗੁੱਡੀਆਂ ਦੀ ਥਾਂ ਕਾਗ਼ਜ਼ ਦੇ ਜਹਾਜ਼ ਉਡਾਉਂਦੀ, ਤਾਰੇ ਵੇਖਦੀ ਅਤੇ ਜਹਾਜ਼ਾਂ ਦੀਆਂ ਤਸਵੀਰਾਂ ਬਣਾਉਂਦੀ ਸੀ।",
